     7	  test(name + ': empty does not write', async () => {
     8	    const outcome = await exportSelection([], () => assert.fail('Unexpected write'));
     9	    assert.deepEqual(outcome, { kind: 'empty' });
    10	  });
    11	  test(name + ': ineligible selection is all-or-nothing', async () => {
    12	    const rows = [{ id: 'a', status: 'ready' }, { id: 'b', status: 'pending' }];
    13	    const outcome = await exportSelection(rows, () => assert.fail('Unexpected partial write'));
    14	    assert.deepEqual(outcome, { kind: 'blocked', ids: ['b'] });
    15	    assert.deepEqual(rows, [{ id: 'a', status: 'ready' }, { id: 'b', status: 'pending' }]);
    16	  });
    17	  test(name + ': ready selection writes the owned protocol once in selection order', async () => {
    18	    const calls = [];
    19	    const rows = [{ id: 'b', status: 'ready' }, { id: 'a', status: 'ready' }];
    20	    const outcome = await exportSelection(rows, async (body) => { calls.push(body); });
    21	    assert.deepEqual(calls, [{ schema: 1, document_ids: ['b', 'a'] }]);
    22	    assert.deepEqual(outcome, { kind: 'sent', ids: ['b', 'a'] });
    23	    assert.deepEqual(rows, [{ id: 'b', status: 'ready' }, { id: 'a', status: 'ready' }]);
    24	  });
    25	  test(name + ': transport errors retain their meaning', async () => {
    26	    const failure = new Error('Storage unavailable');
    27	    await assert.rejects(exportSelection([{ id: 'a', status: 'ready' }], async () => { throw failure; }),
    28	      (error) => error === failure);
    29	  });
    30	  test(name + ': accepted intent does not drift during a pending write', async () => {
    31	    let release;
    32	    const accepted = new Promise((resolve) => { release = resolve; });
    33	    const rows = [{ id: 'a', status: 'ready' }];
    34	    let payload;
    35	    const outcome = exportSelection(rows, async (body) => { payload = body; await accepted; });
    36	    rows[0].id = 'changed'; rows[0].status = 'pending';
    37	    release();
    38	    assert.deepEqual(await outcome, { kind: 'sent', ids: ['a'] });
    39	    assert.deepEqual(payload, { schema: 1, document_ids: ['a'] });
